ALTER TABLE users ADD COLUMN points BIGINT NOT NULL DEFAULT 0;
ALTER TABLE users ADD COLUMN qualifying_spend NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK(qualifying_spend>=0);
CREATE TABLE gift_vouchers (id BIGSERIAL PRIMARY KEY, code UUID UNIQUE NOT NULL, buyer_id BIGINT NOT NULL REFERENCES users, recipient_email VARCHAR(255) NOT NULL, status VARCHAR(255) NOT NULL CHECK(status IN ('PENDING','FAILED','ACTIVE','CANCELLED')), value NUMERIC(14,2) NOT NULL CHECK(value>0), balance NUMERIC(14,2) NOT NULL CHECK(balance>=0 AND balance<=value), created_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NOT NULL, request_key UUID UNIQUE NOT NULL, reward BOOLEAN NOT NULL);
CREATE TABLE voucher_usages (id BIGSERIAL PRIMARY KEY, voucher_id BIGINT NOT NULL REFERENCES gift_vouchers, booking_id BIGINT UNIQUE NOT NULL REFERENCES bookings, amount NUMERIC(14,2) NOT NULL CHECK(amount>0), refunded BOOLEAN NOT NULL DEFAULT FALSE, request_key UUID UNIQUE NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE point_entries (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users, delta BIGINT NOT NULL, source VARCHAR(255) UNIQUE NOT NULL, description VARCHAR(255) NOT NULL, spend NUMERIC(14,2) NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_points_user ON point_entries(user_id,id);
CREATE TABLE shop_products (id BIGSERIAL PRIMARY KEY, name VARCHAR(255) NOT NULL, description VARCHAR(2000) NOT NULL, price NUMERIC(14,2) NOT NULL CHECK(price>=0), stock INTEGER NOT NULL CHECK(stock>=0), active BOOLEAN NOT NULL);
CREATE TABLE shop_orders (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users, booking_id BIGINT REFERENCES bookings, status VARCHAR(255) NOT NULL CHECK(status IN ('PENDING','FAILED','PAID','CANCELLED','EXPIRED','FULFILLED')), delivery VARCHAR(255) NOT NULL CHECK(delivery IN ('PICKUP','ON_BOARD')), total NUMERIC(14,2) NOT NULL CHECK(total>=0), request_key UUID UNIQUE NOT NULL, created_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_orders_user ON shop_orders(user_id,id);
CREATE TABLE shop_order_items (id BIGSERIAL PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES shop_orders, product_id BIGINT NOT NULL REFERENCES shop_products, name VARCHAR(255) NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), price NUMERIC(14,2) NOT NULL CHECK(price>=0), UNIQUE(order_id,product_id));
CREATE TABLE commerce_payments (id BIGSERIAL PRIMARY KEY, kind VARCHAR(255) NOT NULL, purchase_id BIGINT NOT NULL, request_key UUID UNIQUE NOT NULL, outcome VARCHAR(255) NOT NULL CHECK(outcome IN ('SUCCESS','FAILED','CANCELLED')), amount NUMERIC(14,2) NOT NULL CHECK(amount>=0), created_at TIMESTAMPTZ NOT NULL);
